import{_ as e,o as t,c as r,a4 as n}from"./chunks/framework.CzJ_HCFe.js";const m=JSON.parse('{"title":"Mutual Engagement (Kanya-Varavarana) Evidence Audit","description":"","frontmatter":{},"headers":[],"relativePath":"reference/36-engagement-evidence-audit.md","filePath":"reference/36-engagement-evidence-audit.md","lastUpdated":1788546361000}'),i={name:"reference/36-engagement-evidence-audit.md"};function s(o,a,d,l,u,h){return t(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="mutual-engagement-kanya-varavarana-evidence-audit" tabindex="-1">Mutual Engagement (Kanya-Varavarana) Evidence Audit <a class="header-anchor" href="#mutual-engagement-kanya-varavarana-evidence-audit" aria-label="Permalink to &quot;Mutual Engagement (Kanya-Varavarana) Evidence Audit&quot;">​</a></h1><h2 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to &quot;Verdict&quot;">​</a></h2><p>The <code>engagement</code> key now implements a source-verified mutual ritual selection, using the exact common Nakshatras of Muhurta Chintamani&#39;s Kanyavarana and Varavarana/Phaladana passages. The former Purna/Jaya, weekday and fixed-Lagna proxies have been removed.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><ul><li><strong>MC-HINDI-IA</strong> — <em>Muhurta Chintamani</em>, Vivaha-prakarana, “Kanyavarana Muhurta” and “Varavarana (Phaladana) Muhurta,” verses 10-11, printed pp. 103-104; Internet Archive OCR lines 5337-5360.</li><li>Verse 10&#39;s <code>karapidocita-rksha</code> alternative refers to the marriage stars enumerated in verse 55, printed pp. 125-126; OCR lines 6401-6426.</li></ul><h2 id="exact-mutual-election-gate" tabindex="-1">Exact mutual-election gate <a class="header-anchor" href="#exact-mutual-election-gate" aria-label="Permalink to &quot;Exact mutual-election gate&quot;">​</a></h2><p>Kanyavarana admits Uttara Ashadha, Swati, Shravana, all three Purvas, Anuradha, Dhanishtha and Krittika, or the verse-55 marriage stars. Varavarana admits Rohini, all three Uttaras, Krittika and all three Purvas. Every star in the latter list occurs in the former list after its marriage-star expansion.</p><p>The mutual rite therefore has this exact eight-star intersection:</p><ul><li>Rohini and Krittika</li><li>Purva Phalguni, Purva Ashadha and Purva Bhadrapada</li><li>Uttara Phalguni, Uttara Ashadha and Uttara Bhadrapada</li></ul><p>Automation treats that list as a hard slot-time Nakshatra gate.</p><h2 id="manual-boundary" tabindex="-1">Manual boundary <a class="header-anchor" href="#manual-boundary" aria-label="Permalink to &quot;Manual boundary&quot;">​</a></h2><p>Verse 11 also requires a Shubha day, Tithi and Lagna, but does not enumerate those values in this passage. The result is therefore capped for practitioner review until an officiant establishes those three conditions. A one-sided Kanyavarana or Varavarana may use its respective broader list; this profile is specifically for a mutual engagement and gift exchange, not the wedding, compatibility assessment, consent, or a prediction of the relationship.</p>',12)])])}const v=e(i,[["render",s]]);export{m as __pageData,v as default};
